solution:
function solve(c) {
  let terakhirGagal = 0
  for (let n = 1; n <= 100; n++) {
    if (c * n * n >= 2 ** n) terakhirGagal = n
  }
  // Setelah n terakhir yang gagal, 2^n selalu menang.
  return terakhirGagal + 1
}
